#define main inherited_boundary_test_main
#include "../../../tests/flow_boundary_test.cpp"
#undef main
#include <chrono>
#include <iomanip>
int main() {
    std::cout<<std::setprecision(17);
    for(const auto shape:{std::array<int,3>{24,8,0},{128,32,0},{16,16,1},{32,32,1},{24,24,2}}) {
        const auto mesh=rectangle(shape[0],shape[1],shape[2]==0?4:1,shape[2]==2);
        auto c=conditions(mesh,shape[2]==1);c.nu=.1;c.tolerance=1e-6;c.maxIterations=1500;c.profile=true;
        c.pressurePreconditioner=PressurePreconditioner2D::IncompleteCholesky0;
        if(shape[2]==2){c.scenario="manufactured";c.boundaryConditions.clear();}
        FlowResult2D baseline;
        for(bool newton:{false,true}) {
            c.steadyAcceleration=newton?SteadyAcceleration2D::NewtonKrylov:SteadyAcceleration2D::None;
            const auto start=std::chrono::steady_clock::now();
            try {
                const auto r=solveIncompressible2D(mesh,c);
                const auto& step=r.history.back();
                double fieldDifference=0;
                if(newton && baseline.converged && r.converged)for(std::size_t i=0;i<r.u.size();++i)
                    fieldDifference=std::max({fieldDifference,std::abs(r.u[i]-baseline.u[i]),std::abs(r.v[i]-baseline.v[i]),std::abs(r.p[i]-baseline.p[i])});
                std::cout<<"{\"case\":"<<shape[2]<<",\"cells\":"<<mesh.cells.size()<<",\"newton\":"<<(newton?"true":"false")<<",\"converged\":"<<(r.converged?"true":"false")
                    <<",\"evaluations\":"<<step.iteration<<",\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()
                    <<",\"momentum\":"<<step.momentumResidual<<",\"pressureChange\":"<<step.pressureChange<<",\"maxFieldDifference\":"<<fieldDifference<<"}"<<std::endl;
                if(!newton)baseline=r;
            } catch(const std::exception& e) {
                std::cout<<"{\"case\":"<<shape[2]<<",\"cells\":"<<mesh.cells.size()<<",\"newton\":"<<(newton?"true":"false")<<",\"error\":"<<std::quoted(e.what())<<"}"<<std::endl;
            }
        }
    }
}
